      {
        "type": "heading",
        "snippet": "Steps to Update Address Online"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "Log In: Go to the myAadhaar Portal, click Login, enter your 12-digit Aadhaar number and captcha, then enter the OTP sent to your registered mobile number.",
            "snippet_links": [
              {
                "text": "myAadhaar Portal",
                "link": "https://uidai.gov.in/en/my-aadhaar"
              }
            ],
            "reference_indexes": [
              1,
              2,
              3
            ]
          },
          {
            "snippet": "Select Service: Click on the Address Update tab under your services dashboard.",
            "reference_indexes": [
              2,
              3
            ]
          },
          {
            "snippet": "Choose Method: Select Update Aadhaar Online.",
            "reference_indexes": [
              3
            ]
          },
          {
            "snippet": "Enter New Address: Fill in your new residential address details carefully as per your supporting document.",
            "reference_indexes": [
              3,
              4
            ]
          },
          {
            "snippet": "Upload Document: Choose a valid Proof of Address (PoA) document from the drop-down menu (such as a Passport, Voter ID, Bank Passbook, or Utility Bill) and upload a clear copy.",
            "reference_indexes": [
              1,
              3,
              5
            ]
          },
          {
            "snippet": "Pay Fee: Pay the non-refundable update fee of ₹75 online.",
            "reference_indexes": [
              0,
              6
            ]
          },
          {
            "snippet": "Save SRN: Save the generated Service Request Number (SRN) to track your update status."
          }
        ],
        "reference_indexes": [
          0,
          1
        ]
      },
      {
        "type": "heading",
        "snippet": "Requirements & Important Notes"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "Linked Mobile Number: Your mobile number must be linked to your Aadhaar to receive the OTP for online authentication.",
            "reference_indexes": [
              1
            ]
          },
          {
            "snippet": "Processing Time: Most online address updates are completed within 30 days after verification by UIDAI."
          }
        ],
        "reference_indexes": [
